[
  {
    "statement": "Conservation headlands appear to be a highly cost-effective conservation action for increasing butterfly populations on farmland.",
    "citations": [
      "3898",
      "652"
    ]
  },
  {
    "statement": "Conservation headlands involve leaving the headlands in fields unsprayed.",
    "citations": [
      "3898",
      "652"
    ]
  },
  {
    "statement": "Leaving headlands unsprayed increases both butterfly species richness and abundance compared to sprayed headlands.",
    "citations": [
      "3898",
      "652"
    ]
  },
  {
    "statement": "Planting nectar flower mixtures or wildflower strips is a highly effective action for increasing butterfly populations.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Twenty-three studies demonstrate that planting nectar flower mixtures or wildflower strips increases butterfly species richness and abundance compared to conventional field margins or cropped fields.",
    "citations": [
      "3932"
    ]
  },
  {
    "statement": "Planting grass buffer strips or margins around fields shows mixed results but can be beneficial for butterfly populations.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Grass buffer strips can enhance butterfly species richness and abundance.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Grass buffer strips are more beneficial for butterflies when the strips are floristically enhanced or made wider, up to 6 meters, rather than being standard grass-only margins.",
    "citations": [
      "3982"
    ]
  },
  {
    "statement": "Payment schemes that cover conservation costs are widely used.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Payment schemes can be effective for implementing conservation measures for butterflies on farmland.",
    "citations": [
      "3915"
    ]
  }
]

[
  {
    "statement": "There is currently no evidence available on the effectiveness of introducing specialist herbivorous insects as a biological control for invasive plants that degrade butterfly habitats.",
    "citations": []
  },
  {
    "statement": "A systematic search found no studies that directly and quantitatively tested the effects of biological control using specialist herbivorous insects on invasive plants affecting butterfly habitats.",
    "citations": [
      "1277",
      "1599"
    ]
  },
  {
    "statement": "There is evidence that removing or controlling invasive plants can benefit butterfly populations.",
    "citations": [
      "3890"
    ]
  },
  {
    "statement": "Studies have shown increased butterfly abundance, species richness, and habitat use in areas where invasive plants were removed.",
    "citations": [
      "3890"
    ]
  },
  {
    "statement": "No studies have specifically examined the use of specialist herbivorous insects as the control method for invasive plants in butterfly habitats.",
    "citations": []
  },
  {
    "statement": "The lack of evidence means it is not possible to assess whether using specialist herbivorous insects as a biological control would be effective for butterfly conservation efforts.",
    "citations": []
  },
  {
    "statement": "The lack of evidence means it is not possible to assess whether using specialist herbivorous insects as a biological control would have harmful impacts on butterfly conservation efforts.",
    "citations": []
  }
]

