[
  {
    "statement": "Evidence overwhelmingly indicates that milkweed planting and habitat restoration is the most important conservation action for monarch butterflies.",
    "citations": []
  },
  {
    "statement": "Planting parks, gardens and road verges with appropriate native species, including milkweeds, directly increases monarch egg abundance compared to shorter milkweed species.",
    "citations": [
      "3842"
    ]
  },
  {
    "statement": "Monarchs readily use planted milkweed in gardens more than in meadows.",
    "citations": []
  },
  {
    "statement": "Planting native milkweed species is critical for monarch caterpillar growth.",
    "citations": []
  },
  {
    "statement": "Replanting native vegetation including host plants is used by wild monarch butterflies and other species.",
    "citations": [
      "3933"
    ]
  },
  {
    "statement": "Captive rearing has been successfully used for monarchs for over 25 years.",
    "citations": [
      "3916"
    ]
  },
  {
    "statement": "Habitat restoration through native plant establishment remains the primary conservation approach.",
    "citations": []
  },
  {
    "statement": "Direct field evidence shows increased monarch abundance from habitat restoration through native plant establishment.",
    "citations": []
  }
]
